local d = ""

local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function decode(s)
    s = s:gsub("[^" .. b .. "=]", "")
    return (s:gsub(".", function(x)
        if x == "=" then
            return ""
        end
        local n = b:find(x, 1, true) - 1
        local out = ""
        for i = 6, 1, -1 do
            out = out .. ((n % 2^i - n % 2^(i-1)) / 2^(i-1) >= 1 and "1" or "0")
        end
        return out
    end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(x)
        if #x ~= 8 then
            return ""
        end
        local n = 0
        for i = 1, 8 do
            n = n + (x:sub(i, i) == "1" and 2^(8-i) or 0)
        end
        return string.char(n)
    end))
end

local src = decode(d)
local fn = loadstring(src)

if not fn then
    error("Error al reconstruir el script.")
end

return fn()
